    /**
     * Method to retrieve the Diagnosis via DiagnosisFetchOneSummary
     * @param 	summary DiagnosisFetchOneSummary 
     * @return 	DiagnosisFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Diagnosis getDiagnosis( DiagnosisFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DiagnosisFetchOneSummary arg cannot be null" );
    	
    	Diagnosis entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Diagnosis
        	// --------------------------------------
        	CompletableFuture<Diagnosis> futureEntity = queryGateway.query(new FindDiagnosisQuery( new LoadDiagnosisFilter( summary.getDiagnosisId() ) ), ResponseTypes.instanceOf(Diagnosis.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Diagnosis with id " + summary.getDiagnosisId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


